<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['order_id','public_token','method','status','carrier','tracking_number','tracking_url','label_url','destination_postal_code','destination_state','destination_city','destination_neighborhood','destination_address','cod_amount','quoted_amount','quoted_service','parcel_weight','parcel_length','parcel_width','parcel_height','quote_response','skydropx_quotation_id','skydropx_rate_id','skydropx_shipment_id','shipped_at','delivered_at'])]
class Shipment extends Model { use HasFactory; public const METHODS=['moto'=>'Moto','skydropx'=>'Skydropx','cod'=>'Contra entrega']; public const STATUSES=['preparing'=>'Preparando pedido','packing'=>'Empacando','ready'=>'Listo para enviar','in_transit'=>'En camino','delivered'=>'Entregado','exception'=>'Incidencia']; protected function casts():array{return ['quote_response'=>'array','cod_amount'=>'decimal:2','quoted_amount'=>'decimal:2','parcel_weight'=>'decimal:2','shipped_at'=>'datetime','delivered_at'=>'datetime'];} public function order():BelongsTo{return $this->belongsTo(Order::class);} public function events():HasMany{return $this->hasMany(ShipmentEvent::class)->orderByDesc('occurred_at');} public function getPublicUrlAttribute():string{return route('shipments.public',$this->public_token);} }
